const rows=$input.all().map(i=>i.json).filter(x=>x.id_pedido);
const today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Bogota'});
const todays=rows.filter(r=>String(r.fecha)===today && String(r.estado)!=='Cancelado');
const total=todays.reduce((s,r)=>s+Number(r.total_pago||0),0);
const products={}; const hours={};
for(const r of todays){
  let detail=[]; try{detail=JSON.parse(r.detalles_pedido||'[]')}catch{}
  for(const p of detail) products[p.nombre]=(products[p.nombre]||0)+Number(p.cantidad||0);
  const h=String(r.hora||'00').slice(0,2);
  hours[h]=(hours[h]||0)+1;
}
const star=Object.entries(products).sort((a,b)=>b[1]-a[1])[0]||['Sin ventas',0];
const peak=Object.entries(hours).sort((a,b)=>b[1]-a[1])[0]||['--',0];
const peakText=peak[0]==='--'?'Sin pedidos':`${peak[0]}:00-${String(Number(peak[0])+1).padStart(2,'0')}:00`;
const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(n||0));
return [{json:{text:`📊 *REPORTE DIARIO DELIVERYBOT*\n\nFecha: ${today}\n💰 Total vendido: *${money(total)}*\n🧾 Número de pedidos: *${todays.length}*\n🎫 Ticket promedio: *${money(todays.length?total/todays.length:0)}*\n⭐ Producto más vendido: *${star[0]}* (${star[1]} uds.)\n🕒 Hora pico: *${peakText}*`}}];
